const LABELS = {"_comment": "Single source of truth for fault labels. Group A owns this file. A label is TRAINED by Agent 1 only if it has at least min_recordings distinct recordings (checked by agent1_audio/src/prepare_data.py); otherwise it is a hypothesis that only Agent 2 may propose and confirm with checks. Change by PR only.", "version": "0.2.0", "min_recordings": 8, "contexts": ["idle", "startup", "braking", "driving", "unknown"], "labels": [{"id": "normal", "context": "idle", "fr": "Moteur normal", "en": "Normal engine"}, {"id": "belt", "context": "idle", "fr": "Courroie qui siffle", "en": "Squealing belt"}, {"id": "misfire", "context": "idle", "fr": "Raté d'allumage", "en": "Misfire / rough idle"}, {"id": "power_steering", "context": "idle", "fr": "Pompe de direction assistée", "en": "Power steering pump"}, {"id": "low_oil", "context": "idle", "fr": "Manque d'huile", "en": "Low oil"}, {"id": "tappet", "context": "idle", "fr": "Claquement de poussoirs", "en": "Tappet / lifter tick"}, {"id": "knock", "context": "idle", "fr": "Cliquetis / bruit de bielle", "en": "Engine / rod knock"}, {"id": "exhaust_leak", "context": "idle", "fr": "Fuite d'échappement", "en": "Exhaust leak"}, {"id": "vacuum_leak", "context": "idle", "fr": "Prise d'air", "en": "Vacuum leak"}, {"id": "alternator", "context": "idle", "fr": "Alternateur", "en": "Alternator whine / bearing"}, {"id": "diesel_injector", "context": "idle", "fr": "Injecteur diesel", "en": "Diesel injector knock"}, {"id": "normal_brakes", "context": "braking", "fr": "Freins normaux", "en": "Normal brakes"}, {"id": "worn_brakes", "context": "braking", "fr": "Freins usés", "en": "Worn brakes"}, {"id": "normal_startup", "context": "startup", "fr": "Démarrage normal", "en": "Normal startup"}, {"id": "dead_battery", "context": "startup", "fr": "Batterie faible", "en": "Weak / dead battery"}, {"id": "bad_ignition", "context": "startup", "fr": "Allumage défaillant", "en": "Bad ignition"}, {"id": "starter_click", "context": "startup", "fr": "Démarreur qui claque", "en": "Starter clicking"}, {"id": "timing_chain", "context": "startup", "fr": "Chaîne de distribution", "en": "Timing chain rattle"}, {"id": "turbo", "context": "driving", "fr": "Turbo", "en": "Turbo whistle / failure"}, {"id": "wheel_bearing", "context": "driving", "fr": "Roulement de roue", "en": "Wheel bearing"}, {"id": "cv_joint", "context": "driving", "fr": "Cardan", "en": "CV joint"}, {"id": "transmission", "context": "driving", "fr": "Boîte de vitesses", "en": "Transmission"}, {"id": "suspension", "context": "driving", "fr": "Suspension", "en": "Suspension clunk"}], "hypotheses_only": {"ids": ["exhaust_leak", "vacuum_leak", "alternator", "diesel_injector", "starter_click", "timing_chain", "turbo", "wheel_bearing", "cv_joint", "transmission", "suspension"]}};

// Agent 2, node "Prepare input" (Code node source). Owner: B2. Port of agent2_diagnosis/agent2.py (describe_audio,
// user_message). The build script agent2_diagnosis/build_workflow.py wraps this function into the n8n Code node
// and embeds P3, P4, P5 (prompts/*.md) and contracts/labels.json. Test: node n8n/code_nodes/test_agent2_nodes.js
//
// prepare(c, P3, SYSTEM, LABELS)
//   c      : case record (contracts/case_record.schema.json); c.audio is the Agent 1 output
//   P3     : audio text template; SYSTEM : {1: P4 text, 2: P5 text}
// returns  : { case, ctx, system_prompt, user_message, filters_json }

function prepare(c, P3, SYSTEM, LABELS, mode) {  // mode: 'tool' (default) or 'prefetch' (passages are added later by "Retrieve passages")
  const MAX_ROUNDS = 2;
  const labelEn = Object.fromEntries(LABELS.labels.map((l) => [l.id, l.en]));
  const labelNames = Object.fromEntries(LABELS.labels.map((l) => [l.id, l]));
  const known = [...new Set([...Object.keys(labelEn), ...LABELS.hypotheses_only.ids])].sort();
  const n = (c.round || 0) + 1; // pass number = check rounds answered + 1
  const allowNew = n <= MAX_ROUNDS;
  const diagnosis = c.diagnosis || [];
  const lang = (c.user_input && c.user_input.language) || 'unknown';

  const a = c.audio;
  let audioText = "No usable audio: rely on the user's description only.";
  if (a && a.status === 'ok') {
    const top = a.top3 || [];
    const score = a.anomaly_score;
    const pct = (p) => Math.round(p * 100) + ' %';
    const name = (l) => (labelNames[l] ? labelNames[l][lang] || labelNames[l].en : l);
    // anomaly_score is a percentile against HEALTHY engines (0.5 = typical healthy sound), see Agent 1's INTEGRATION.md
    const unusualness = score == null ? 'unknown' : score >= 0.95 ? 'very high' : score >= 0.8 ? 'high' : 'normal range';
    // decision table of Agent 1's guide, computed here so a small model does not have to infer it
    const normal = String(a.label || '').startsWith('normal');
    const lines = [];
    if (a.confidence === 'low') lines.push("The audio is not conclusive: rely on the driver's description and on the checks more than on the sound.");
    if (score != null && !normal && score >= 0.8) lines.push('The sound class and the anomaly score agree: start from the most likely classes.');
    if (score != null && normal && score < 0.8) lines.push('The engine probably sounds healthy: ask whether the noise is intermittent and suggest recording again when it happens.');
    if (score != null && normal && score >= 0.95) {
      lines.push('Very unusual sound outside the classes the audio model knows: also consider these faults and separate them with checks: ' +
        LABELS.hypotheses_only.ids.map((i) => i.replace(/_/g, ' ')).join(', ') + '.');
    }
    const vars = {
      label_name: name(a.label),
      prob: top.length ? pct(top[0].prob) : 'n/a',
      others: top.slice(1).map((t) => name(t.label) + ' (' + pct(t.prob) + ')').join(', ') || 'none',
      confidence: a.confidence,
      unusualness,
      summary: (a.description && a.description.summary) || '',
      warnings: (a.warnings || []).join('; ') || 'none',
      reading: lines.join(' ') || 'none',
    };
    audioText = P3.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
  }

  const parts = [
    'Vehicle: ' + JSON.stringify(c.vehicle || {}),
    "Driver's description: " + ((c.symptom && c.symptom.description) || ''),
    "Driver's language: " + lang,
    audioText,
    'Label ids you may use: ' + JSON.stringify(known),
  ];
  if (diagnosis.length) {
    const answers = Object.fromEntries((c.check_answers || []).map((x) => [x.check_id, x.answer]));
    const asked = diagnosis.flatMap((d) => d.checks).map((k) => `${k.id}: ${k.q} -> ${answers[k.id] || '(no answer)'}`);
    parts.push(
      'Previous causes: ' + JSON.stringify(diagnosis[diagnosis.length - 1].causes),
      'Checks asked and answers:
' + asked.join('
'),
      'New checks allowed: ' + (allowNew ? 'yes' : 'no')
    );
  }
  if (mode !== 'prefetch') parts.push('Use the rag_search tool to get the manual passages. Cite chunk_id values exactly as returned.');

  // search queries (port of queries() in agent2.py): symptom + sound label, the label alone, symptom + the driver's answers
  const label = labelEn[(a && a.label) || ''] || '';
  const symptom = (c.symptom && c.symptom.description) || '';
  const answered = (c.check_answers || []).map((x) => x.answer).join(' ');
  const queries = [...new Set([`${symptom} ${label}`, label ? `${label} causes` : '', answered ? `${symptom} ${answered}` : ''].map((q) => q.trim()).filter(Boolean))];

  const v = c.vehicle || {};
  const filters = { section: ['symptoms', 'causes', 'codes'] };
  for (const k of ['make', 'model', 'year']) if (v[k]) filters[k] = v[k];

  return {
    case: c,
    ctx: { n, allow_new: allowNew, asked: diagnosis.reduce((s, d) => s + d.checks.length, 0), language: lang },
    system_prompt: SYSTEM[n === 1 ? 1 : 2],
    user_message: parts.join('
'),
    filters_json: JSON.stringify(filters),
    queries,
  };
}

return { json: prepare($json.body || $json, P3, SYSTEM, LABELS, 'tool') };

const SUPPORT = true;
const LABELS = {"_comment": "Single source of truth for fault labels. Group A owns this file. A label is TRAINED by Agent 1 only if it has at least min_recordings distinct recordings (checked by agent1_audio/src/prepare_data.py); otherwise it is a hypothesis that only Agent 2 may propose and confirm with checks. Change by PR only.", "version": "0.2.0", "min_recordings": 8, "contexts": ["idle", "startup", "braking", "driving", "unknown"], "labels": [{"id": "normal", "context": "idle", "fr": "Moteur normal", "en": "Normal engine"}, {"id": "belt", "context": "idle", "fr": "Courroie qui siffle", "en": "Squealing belt"}, {"id": "misfire", "context": "idle", "fr": "Raté d'allumage", "en": "Misfire / rough idle"}, {"id": "power_steering", "context": "idle", "fr": "Pompe de direction assistée", "en": "Power steering pump"}, {"id": "low_oil", "context": "idle", "fr": "Manque d'huile", "en": "Low oil"}, {"id": "tappet", "context": "idle", "fr": "Claquement de poussoirs", "en": "Tappet / lifter tick"}, {"id": "knock", "context": "idle", "fr": "Cliquetis / bruit de bielle", "en": "Engine / rod knock"}, {"id": "exhaust_leak", "context": "idle", "fr": "Fuite d'échappement", "en": "Exhaust leak"}, {"id": "vacuum_leak", "context": "idle", "fr": "Prise d'air", "en": "Vacuum leak"}, {"id": "alternator", "context": "idle", "fr": "Alternateur", "en": "Alternator whine / bearing"}, {"id": "diesel_injector", "context": "idle", "fr": "Injecteur diesel", "en": "Diesel injector knock"}, {"id": "normal_brakes", "context": "braking", "fr": "Freins normaux", "en": "Normal brakes"}, {"id": "worn_brakes", "context": "braking", "fr": "Freins usés", "en": "Worn brakes"}, {"id": "normal_startup", "context": "startup", "fr": "Démarrage normal", "en": "Normal startup"}, {"id": "dead_battery", "context": "startup", "fr": "Batterie faible", "en": "Weak / dead battery"}, {"id": "bad_ignition", "context": "startup", "fr": "Allumage défaillant", "en": "Bad ignition"}, {"id": "starter_click", "context": "startup", "fr": "Démarreur qui claque", "en": "Starter clicking"}, {"id": "timing_chain", "context": "startup", "fr": "Chaîne de distribution", "en": "Timing chain rattle"}, {"id": "turbo", "context": "driving", "fr": "Turbo", "en": "Turbo whistle / failure"}, {"id": "wheel_bearing", "context": "driving", "fr": "Roulement de roue", "en": "Wheel bearing"}, {"id": "cv_joint", "context": "driving", "fr": "Cardan", "en": "CV joint"}, {"id": "transmission", "context": "driving", "fr": "Boîte de vitesses", "en": "Transmission"}, {"id": "suspension", "context": "driving", "fr": "Suspension", "en": "Suspension clunk"}], "hypotheses_only": {"ids": ["exhaust_leak", "vacuum_leak", "alternator", "diesel_injector", "starter_click", "timing_chain", "turbo", "wheel_bearing", "cv_joint", "transmission", "suspension"]}};

// Agent 2, node "Ground and decide" (Code node source). Owner: B2. Port of agent2_diagnosis/agent2.py
// (build_causes, build_checks, is_conclusive, safety_stop). Wrapped by agent2_diagnosis/build_workflow.py.
// Test: node n8n/code_nodes/test_agent2_nodes.js
//
// postprocess(ctx, agentOut, LABELS)
//   ctx      : ctx from "Prepare input" ({n, allow_new, asked, language})
//   agentOut : output of the AI Agent node: {output: "<LLM text>", intermediateSteps: [{observation}]}
// returns    : item for validate_output.js: {agent, output (agent2_output or null), retrieved, insufficient, reason}
// Rules: only passages that /search returned count; uncited causes and checks are dropped; conclusive, safety_stop,
// label validity and check ids are decided here, not by the LLM.

function postprocess(ctx, agentOut, LABELS) {
  const LEVELS = ['exact_model', 'make', 'generic', 'none'];
  const SAFETY = /frein|brake|direction|steering|surchauffe|overheat|temp[ée]rature|oil pressure|pression d.huile/i;
  const CONCLUSIVE_PROB = 0.6, CONCLUSIVE_GAP = 0.2;
  const DEFAULT_MESSAGE = { fr: 'Pour confirmer, répondez à ces questions :', en: 'To confirm, please answer these questions:' };
  // LLMs add spaces, brackets or quotes around ids: ' [clio4ph1fr_p225_c1]' -> 'clio4ph1fr_p225_c1'
  const cleanId = (x) => String(x == null ? '' : x).replace(/^[\s\[('"]+|[\s\])'",.;]+$/g, '');
  // small models sometimes answer with a machine id ('dead_battery') as the cause name: show the label's name instead
  const labelNames = Object.fromEntries(LABELS.labels.map((l) => [l.id, l]));
  const readable = (name, label) => {
    if (!(name in labelNames) && !/^[A-Za-z0-9]+(_[A-Za-z0-9]+)+$/.test(name)) return name; // exactly a label id, or looks like an id
    const l = labelNames[name] || labelNames[label];
    return l ? l[ctx.language] || l.en : name.replace(/_/g, ' ');
  };
  const known = new Set([...LABELS.labels.map((l) => l.id), ...LABELS.hypotheses_only.ids]);

  // 1. the passages the agent really retrieved (tool results)
  const byId = {};
  let level = 'exact_model';
  for (const step of agentOut.intermediateSteps || []) {
    let obs = step.observation;
    if (typeof obs === 'string') {
      try { obs = JSON.parse(obs); } catch (e) { continue; }
    }
    if (!obs || !Array.isArray(obs.passages)) continue;
    for (const p of obs.passages) byId[p.chunk_id] = p;
    if (LEVELS.indexOf(obs.fallback_level) > LEVELS.indexOf(level)) level = obs.fallback_level;
  }
  const retrieved = Object.keys(byId);
  const fail = (reason) => ({ agent: 'agent2_output', output: null, retrieved, insufficient: true, reason });
  if (!retrieved.length) return fail('no manual passages retrieved');

  // 2. the LLM answer
  let raw = agentOut.output;
  if (typeof raw === 'string') {
    const m = raw.match(/\{[\s\S]*\}/);
    try { raw = m ? JSON.parse(m[0]) : {}; } catch (e) { raw = {}; }
  }
  raw = raw || {};

  // 3. grounded causes
  let causes = [];
  for (const c of raw.causes || []) {
    const ids = (c.sources || []).map(cleanId).filter((s) => byId[s]);
    if (!ids.length || !c.name) continue;
    let prob = Math.max(Number(c.prob) || 0, 0);
    if (String(c.status || '').toLowerCase() === 'contradicted') prob = Math.min(prob, 0.05); // P5: an answer shows it is not the cause
    const label = known.has(c.label) ? c.label : null;
    causes.push({
      name: readable(String(c.name).trim(), label),
      label,
      prob,
      evidence: (c.evidence || []).map(String).concat(ids.map((i) => 'passage ' + i)),
    });
  }
  causes = causes.sort((a, b) => b.prob - a.prob).slice(0, 5);
  if (!causes.length) return fail('the passages support no cause (or the model cited none)');
  const total = causes.reduce((s, c) => s + c.prob, 0) || 1;
  causes.forEach((c) => { c.prob = Math.round((c.prob / total) * 1000) / 1000; });

  // 4. grounded checks
  let checks = [];
  if (ctx.allow_new) {
    for (const c of raw.checks || []) {
      const p = byId[cleanId(c.source)];
      if (!p || !c.q || checks.length >= 5) continue;
      let kind = ['yes_no', 'choice', 'free_text'].includes(c.answer_type) ? c.answer_type : 'yes_no';
      const choices = (c.choices || []).map(String);
      if (kind === 'choice' && !choices.length) kind = 'free_text';
      const chk = {
        id: 'c' + (ctx.asked + checks.length + 1),
        q: c.q,
        why: c.why || '',
        answer_type: kind,
        citation: { chunk_id: p.chunk_id, source: p.source, page: p.page === undefined ? null : p.page, verified: true },
      };
      if (kind === 'choice') chk.choices = choices;
      checks.push(chk);
    }
  }

  // 5. decisions
  const second = causes.length > 1 ? causes[1].prob : 0;
  const isConclusive = causes[0].prob >= CONCLUSIVE_PROB && causes[0].prob - second >= CONCLUSIVE_GAP;
  const conclusive = ctx.n === 1 && checks.length ? false : isConclusive;
  if (conclusive) checks = [];
  const top = causes[0];
  const message = typeof raw.message_to_user === 'string' ? raw.message_to_user : '';
  const output = {
    pass: ctx.n,
    causes,
    checks,
    conclusive,
    message_to_user: message || (checks.length ? DEFAULT_MESSAGE[ctx.language] || DEFAULT_MESSAGE.en : ''),
    // most likely cause decides; less likely risky causes are covered by the caution sentence the prompt asks for
    safety_stop: SAFETY.test(top.name + ' ' + (top.label || '')) || top.label === 'worn_brakes',
  };
  return { agent: 'agent2_output', output, retrieved, insufficient: false, reason: null, fallback_level: level };
}

// supportFilter(agentOut, search, filters, top)  [async, run just before postprocess]
// A citation that exists is not a citation that supports: for the `top` likeliest causes, search the cause's own name
// (the service reranks and drops weak passages) and keep the cause only if one of its cited passages comes back.
// Port of supported_causes() in agent2_diagnosis/agent2.py. Returns agentOut with `output` replaced by the filtered answer.
async function supportFilter(agentOut, search, filters, top) {
  const cleanId = (x) => String(x == null ? '' : x).replace(/^[\s\[('"]+|[\s\])'",.;]+$/g, '');
  const have = new Set();
  for (const step of agentOut.intermediateSteps || []) {
    let obs = step.observation;
    if (typeof obs === 'string') {
      try { obs = JSON.parse(obs); } catch (e) { continue; }
    }
    for (const p of (obs && obs.passages) || []) have.add(p.chunk_id);
  }
  let raw = agentOut.output;
  if (typeof raw === 'string') {
    const m = raw.match(/\{[\s\S]*\}/);
    try { raw = m ? JSON.parse(m[0]) : null; } catch (e) { raw = null; }
  }
  if (!raw || !Array.isArray(raw.causes)) return agentOut;
  const ranked = [...raw.causes].sort((a, b) => (Number(b.prob) || 0) - (Number(a.prob) || 0));
  const keep = [];
  for (let n = 0; n < ranked.length; n++) {
    const c = ranked[n];
    const ids = (c.sources || []).map(cleanId).filter((i) => have.has(i));
    if (n < (top || 3) && ids.length && c.name) {
      const res = await search(String(c.name), filters, 8);
      const back = new Set((res.passages || []).map((p) => p.chunk_id));
      if (!ids.some((i) => back.has(i))) continue; // cited passages do not talk about this cause
    }
    keep.push(c);
  }
  return { ...agentOut, output: { ...raw, causes: keep } };
}

const ctx = $('Prepare input').first().json.ctx;
const search = (query, filters, top_k) => this.helpers.httpRequest({
  method: 'POST', url: "http://rag-service:8002/search", body: { query, filters, top_k, rerank: true }, json: true });
const answer = { output: $json.output, intermediateSteps: $json.intermediateSteps };
const checked = SUPPORT ? await supportFilter(answer, search, JSON.parse($('Prepare input').first().json.filters_json), 3) : answer;
return { json: postprocess(ctx, checked, LABELS) };

// n8n Code node ("Run Once for Each Item"), placed right after Agent 2 or Agent 3.
// Same rules as agent3_repair/guardrails/checks.py (R2, R3, R4). Keep both in sync.
//
// Expects on the item:
//   $json.agent     : "agent2_output" | "agent3_output"
//   $json.output    : the LLM answer, already parsed as JSON
//   $json.retrieved : array of chunk_id returned by /search for this case
// Returns the item with { valid: bool, problems: [...] } so an IF node can retry once
// and then fall back to the "insufficient information" answer.

const SAFETY = /frein|brake|direction|steering|surchauffe|overheat|temp[ée]rature/i;
const KEEP_DRIVING = /continuer [àa] rouler|vous pouvez rouler|keep driving|safe to drive|pouvez continuer/i;

const agent = $json.agent;
const out = $json.output || {};
const retrieved = new Set($json.retrieved || []);
const problems = [];

const items = agent === 'agent2_output' ? (out.checks || []) : (out.steps || []);
for (const it of items) {
  const who = it.id || `step ${it.n}`;
  const c = it.citation || {};
  if (!c.chunk_id) problems.push(`R2 ${who}: no citation`);
  else if (!retrieved.has(c.chunk_id)) problems.push(`R2 ${who}: cites ${c.chunk_id}, not retrieved`);
}

const text = JSON.stringify(out);
const firstCause = (out.causes && out.causes[0] && out.causes[0].name) || '';
const safety = SAFETY.test(out.fault || '') || SAFETY.test(firstCause);
if (safety && KEEP_DRIVING.test(text)) problems.push('R3 safety fault: suggests the car can be driven');

if (agent === 'agent3_output') {
  if (safety && !(out.safety_warnings || []).length) problems.push('R3 safety fault without safety_warnings');
  if ((out.confidence === 'low' || out.difficulty === 'mechanic_only') && !out.see_mechanic)
    problems.push('R4 low confidence but see_mechanic is false');
  if (out.status === 'ok' && !(out.steps || []).length) problems.push('R1 status ok but no steps');
}

return { json: { ...$json, valid: problems.length === 0, problems } };
